// ---------- III-5 Whose rule? ----------
const CRIT = { play: ['waited longest', 'most riders', 'nearest stop', 'asked for the ramp'], case: ['waited longest', 'most-borrowed title', 'rare subject', 'children’s card'] };
const CASES = { play: [[[25, 2, 1, 0], [5, 9, 3, 0]], [[8, 3, 4, 1], [10, 6, 1, 0]], [[30, 1, 5, 0], [12, 4, 2, 0]], [[6, 1, 1, 1], [7, 8, 2, 0]], [[40, 1, 9, 0], [2, 2, 1, 0]], [[15, 5, 2, 0], [14, 5, 6, 1]]], case: [[[20, 1, 0, 0], [3, 9, 0, 0]], [[5, 2, 1, 0], [6, 8, 0, 0]], [[9, 1, 1, 1], [12, 7, 0, 0]], [[30, 3, 0, 0], [4, 3, 1, 1]], [[2, 9, 0, 0], [25, 1, 1, 0]], [[10, 5, 0, 1], [10, 5, 1, 0]]] };
