// ---------- III-7 What is it looking at? ----------
function horsePics(r, n, mark) { return R(n, (i) => { const lab = i % 2, px = R(64, () => (r.chance(0.18) ? 1 : 0)); if (lab) { for (const k of [27, 28, 35, 36, 29, 37]) px[k] = r.chance(0.7) ? 1 : px[k]; } if (lab && mark) { px[0] = 1; px[1] = 1; px[8] = 1; px[9] = 1; } else { px[0] = 0; px[1] = 0; px[8] = 0; px[9] = 0; } return [px, lab]; }); }
