function hansModel(s) { if (!looked.has(s.sig)) { if (looked.size > 10) looked.clear(); const tr = horsePics(new RNG(s.sig), 80, true); looked.set(s.sig, logistic(tr.map((t) => t[0]), tr.map((t) => t[1]), { lr: 0.5, iters: 300 })); } return looked.get(s.sig); }
