  teach: ['Notice when a learner is right for a reason you did not intend.', 'Take the suspected cue away and test again.', 'Fix the test so the shortcut no longer works.'],
  init(round, ctx) { const r = ctx.rng(round); if (round === 'case') { const I = ctx.caseData.importance; return { round, inputs: [['how often a title was borrowed last month', I.lastMonth], ['the quality of the book', I.quality]], seen: [0, 0], mark: -1 }; } if (round === 'twist') { const sig = r.int(1, 1e9); return { round, sig, test: horsePics(ctx.rng('test'), 40, true), cover: -1, tried: [] }; } return { round, sees: true, knows: true, res: {}, pick: -1, seed: 0 }; },
