    if (s.round === 'twist') { const cols = 10, sz = Math.min(64 * u, (A.w - 20 * u) / cols - 8 * u), c = sz / 8; title(b, 'Test pictures', 'tap a corner of the first picture to cover that corner on all of them'); s.test.slice(0, 20).forEach(([px, lab], i) => { const X = A.x + (i % cols) * (sz + 8 * u), Y = A.y + 60 * u + Math.floor(i / cols) * (sz + 26 * u); px.forEach((v, k) => { const x = k % 8, y = Math.floor(k / 8), cov = s.cover >= 0 && x >= QUAD[s.cover][0] && x < QUAD[s.cover][0] + 4 && y >= QUAD[s.cover][1] && y < QUAD[s.cover][1] + 4; g.fillStyle = cov ? '#c9cfd8' : v ? INK : '#fff'; g.fillRect(X + x * c, Y + y * c, c, c); }); b.box(X, Y, sz, sz, { color: INK2 }); b.label(lab ? 'horse' : 'other', X, Y + sz + 10 * u, { size: 9.5, color: INK2 }); }); QUAD.forEach((q, k) => card(b, 'c' + k, A.x + k * 150 * u, A.y + A.h - 44 * u, 142 * u, 36 * u, 'cover ' + ['top left', 'top right', 'bottom left', 'bottom right'][k], { size: 11, sel: s.cover === k })); return; }
